	private static Dataset jenaDataset() {
		Dataset dataset = DatasetFactory.createTxnMem();
		dataset.begin(ReadWrite.WRITE);
		var jenaModel = dataset.getDefaultModel();
		for (org.eclipse.rdf4j.model.Statement statement : RealEstateOracleFixtureProfile.generate()) {
			jenaModel.add(resource(jenaModel, statement.getSubject()),
					jenaModel.createProperty(statement.getPredicate().stringValue()), rdfNode(jenaModel, statement.getObject()));
		}
		dataset.commit();
		dataset.end();
		return dataset;
	}

	private static List<QuerySolution> select(Dataset dataset, String query) {
		ArrayList<QuerySolution> rows = new ArrayList<>();
		dataset.begin(ReadWrite.READ);
		try {
			try (QueryExecution execution = QueryExecution.dataset(dataset).query(query).build()) {
				ResultSet result = execution.execSelect();
				while (result.hasNext()) {
					var solution = result.nextSolution();
					rows.add(solution);
				}
			}
		} finally {
			dataset.end();
		}
		return rows;
	}

	private static QuerySolution rowByUri(List<QuerySolution> rows, String variable, String uri) {
		return rows.stream().filter(row -> uriIs(row, variable, uri)).findFirst().orElse(null);
	}

	private static boolean containsUri(List<QuerySolution> rows, String variable, String uri) {
		return rowByUri(rows, variable, uri) != null;
	}

	private static long countUri(List<QuerySolution> rows, String variable, String uri) {
		return rows.stream().filter(row -> uriIs(row, variable, uri)).count();
	}

	private static boolean uriIs(QuerySolution row, String variable, String uri) {
		RDFNode value = row.get(variable);
		return value != null && value.isURIResource() && uri.equals(value.asResource().getURI());
	}

	private static org.apache.jena.rdf.model.Resource resource(org.apache.jena.rdf.model.Model model,
			Resource resource) {
		if (resource instanceof IRI iri) {
			return model.createResource(iri.stringValue());
		}
		if (resource instanceof BNode bNode) {
			return model.createResource(AnonId.create(bNode.getID()));
		}
		throw new IllegalArgumentException("Unsupported RDF4J resource " + resource);
	}

	private static RDFNode rdfNode(org.apache.jena.rdf.model.Model model, Value value) {
		if (value instanceof Resource resource) {
			return resource(model, resource);
		}
		if (value instanceof Literal literal) {
			Optional<String> language = literal.getLanguage();
			if (language.isPresent()) {
				return ResourceFactory.createLangLiteral(literal.getLabel(), language.get());
			}
			RDFDatatype datatype = TypeMapper.getInstance().getSafeTypeByName(literal.getDatatype().stringValue());
			return ResourceFactory.createTypedLiteral(literal.getLabel(), datatype);
		}
		throw new IllegalArgumentException("Unsupported RDF4J value " + value);
	}
